"use client";

import { cn } from "@/lib/utils";
import {
  CanvasStage,
  ImageFallback,
} from "@/registry/ivan/components/canvas-stage/canvas-stage";
import { centeredFocus } from "@/registry/ivan/lib/image-cover";

import { blastPrintDefaults } from "./blast-print-material";
import { BlastPrintScene } from "./blast-print-scene";
import type { BlastPrintSceneProps } from "./blast-print-scene";

export interface BlastPrintProps extends BlastPrintSceneProps {
  className?: string;
  label?: string;
}

const defaultLabel =
  "A picture printed as an ordered dither, bleached and reprinted in color by a click";

export const BlastPrint = ({
  className,
  label = defaultLabel,
  src,
  focus = centeredFocus,
  ink = blastPrintDefaults.ink,
  paper = blastPrintDefaults.paper,
  paused = blastPrintDefaults.paused,
  ...sceneProps
}: BlastPrintProps) => (
  <CanvasStage
    className={cn("touch-pan-y", className)}
    fallback={<ImageFallback focus={focus} src={src} />}
    ground={ink}
    label={label}
    paused={paused}
  >
    {(isAnimating) => (
      <BlastPrintScene
        {...sceneProps}
        focus={focus}
        ink={ink}
        paper={paper}
        paused={!isAnimating}
        src={src}
      />
    )}
  </CanvasStage>
);

"use client";

import { useFrame, useThree } from "@react-three/fiber";
import { useEffect, useMemo, useRef } from "react";
import { PlaneGeometry, Vector3 } from "three";
import type { Intersection, Mesh, Raycaster, WebGLRenderer } from "three";

import { usePrintImage } from "@/registry/ivan/hooks/use-print-image";
import type { PrintImage } from "@/registry/ivan/hooks/use-print-image";
import { createBlueNoiseTexture } from "@/registry/ivan/lib/blue-noise";
import {
  centeredFocus,
  readViewport,
  setCoverImage,
} from "@/registry/ivan/lib/image-cover";
import type { ImageFocus } from "@/registry/ivan/lib/image-cover";
import { orderedDitherIndex } from "@/registry/ivan/lib/ordered-print";
import type { OrderedDither } from "@/registry/ivan/lib/ordered-print";
import { samplePalette } from "@/registry/ivan/lib/palette";
import type { Rgb } from "@/registry/ivan/lib/palette";
import { PointerTrace } from "@/registry/ivan/lib/pointer-trace";
import type { PointerSample } from "@/registry/ivan/lib/pointer-trace";
import {
  createSpring,
  driveSpring,
  frameStep,
} from "@/registry/ivan/lib/spring";

import { BlastPrintMaterial, blastPrintDefaults } from "./blast-print-material";
import { advanceBlast, blastLength, createBlast } from "./blast-timeline";
import type { StagePoint } from "./blast-timeline";

export interface BlastPrintSceneProps {
  src: string;
  focus?: ImageFocus;
  ink?: string;
  paper?: string;
  dither?: OrderedDither;
  cell?: number;
  threshold?: number;
  auraRadius?: number;
  blasts?: number;
  paused?: boolean;
}

interface BlastLook {
  ink: string;
  paper: string;
  dither: OrderedDither;
  cell: number;
  threshold: number;
  auraRadius: number;
}

interface BlastFrameInput {
  delta: number;
  paused: boolean;
  pointer: PointerSample;
}

const followSpring = { damping: 16, stiffness: 120 } as const;
const auraSpring = { damping: 11, stiffness: 90 } as const;
const auraBase = 0.24;
const maxAuraStrength = 1.2;
const frameCenter: StagePoint = { x: 0.5, y: 0.5 };

const hitEverywhere = function hitEverywhere(
  this: Mesh,
  _raycaster: Raycaster,
  intersects: Intersection[]
) {
  intersects.push({ distance: 0, object: this, point: new Vector3() });
};

class BlastPrintRig {
  readonly material = new BlastPrintMaterial();
  readonly geometry = new PlaneGeometry(1, 1);
  private readonly blueNoise = createBlueNoiseTexture();
  private readonly trace = new PointerTrace();
  private readonly blast = createBlast();
  private readonly aura = {
    strength: createSpring(0),
    x: createSpring(0.4),
    y: createSpring(0.7),
  };
  private cell: number = blastPrintDefaults.cell;
  private request: StagePoint | null = null;

  constructor() {
    this.material.uniforms.uBlueNoise.value = this.blueNoise;
  }

  applyLook({ ink, paper, dither, cell, threshold, auraRadius }: BlastLook) {
    const { uniforms } = this.material;
    uniforms.uInk.value.set(ink);
    uniforms.uPaper.value.set(paper);
    uniforms.uDither.value = orderedDitherIndex(dither);
    uniforms.uThreshold.value = threshold;
    uniforms.uAuraRadius.value = auraBase * auraRadius;
    this.cell = cell;
  }

  applyImage(image: PrintImage | null, focus: ImageFocus) {
    setCoverImage(this.material.uniforms, image, focus);
  }

  applyPalette(palette: readonly Rgb[]) {
    const inks = this.material.uniforms.uPalette.value;
    for (const [index, [red, green, blue]] of palette.entries()) {
      inks[index]?.set(red / 255, green / 255, blue / 255);
    }
  }

  detonate(origin: StagePoint) {
    this.request = origin;
  }

  advance({ delta, paused, pointer }: BlastFrameInput) {
    const { aura, blast, trace } = this;
    const { uniforms } = this.material;
    const step = frameStep(delta);
    const isMoving = !paused;
    trace.update(pointer, step, isMoving);
    advanceBlast(blast, {
      mode: isMoving ? "running" : "still",
      request: this.request,
      step,
    });
    this.request = null;

    const targetX = trace.isActive ? trace.x : aura.x.value;
    const targetY = trace.isActive ? trace.y : aura.y.value;
    driveSpring(aura.x, targetX, followSpring, step, isMoving);
    driveSpring(aura.y, targetY, followSpring, step, isMoving);
    const isBlasting = blast.time - blast.firedAt < blastLength;
    driveSpring(
      aura.strength,
      trace.isActive && !isBlasting ? 1 : 0,
      auraSpring,
      step,
      isMoving
    );

    const { frame } = blast;
    uniforms.uTime.value = blast.time;
    uniforms.uAuraStrength.value = Math.min(
      Math.max(aura.strength.value, 0),
      maxAuraStrength
    );
    uniforms.uRing.value = frame.ring;
    uniforms.uFront.value = frame.front;
    uniforms.uReprint.value = frame.reprint;
    uniforms.uColor.value = frame.color;
  }

  readonly handleBeforeRender = (renderer: WebGLRenderer) => {
    const { uniforms } = this.material;
    const viewport = readViewport(uniforms, renderer);
    uniforms.uCell.value = this.cell * renderer.getPixelRatio();
    uniforms.uAura.value.set(
      this.aura.x.value * viewport.z,
      this.aura.y.value * viewport.w
    );
    uniforms.uBlast.value.set(
      this.blast.origin.x * viewport.z,
      this.blast.origin.y * viewport.w
    );
  };

  dispose() {
    this.material.dispose();
    this.geometry.dispose();
    this.blueNoise.dispose();
  }
}

export const BlastPrintScene = ({
  src,
  focus = centeredFocus,
  ink = blastPrintDefaults.ink,
  paper = blastPrintDefaults.paper,
  dither = blastPrintDefaults.dither,
  cell = blastPrintDefaults.cell,
  threshold = blastPrintDefaults.threshold,
  auraRadius = blastPrintDefaults.auraRadius,
  blasts = blastPrintDefaults.blasts,
  paused = blastPrintDefaults.paused,
}: BlastPrintSceneProps) => {
  const invalidate = useThree((state) => state.invalidate);
  const rig = useMemo(() => new BlastPrintRig(), []);
  const image = usePrintImage(src);
  const palette = useMemo(
    () => (image ? samplePalette(image.element) : null),
    [image]
  );

  useEffect(() => () => rig.dispose(), [rig]);

  useEffect(() => {
    rig.applyLook({ auraRadius, cell, dither, ink, paper, threshold });
    invalidate();
  }, [auraRadius, cell, dither, ink, invalidate, paper, rig, threshold]);

  useEffect(() => {
    rig.applyImage(image, { x: focus.x, y: focus.y });
    if (palette) {
      rig.applyPalette(palette);
    }
    invalidate();
  }, [focus.x, focus.y, image, invalidate, palette, rig]);

  const handledBlasts = useRef(blasts);
  useEffect(() => {
    if (blasts !== handledBlasts.current) {
      handledBlasts.current = blasts;
      rig.detonate(frameCenter);
      invalidate();
    }
  }, [blasts, invalidate, rig]);

  useFrame((state, delta) => {
    rig.advance({ delta, paused, pointer: state.pointer });
  });

  return (
    <mesh
      frustumCulled={false}
      geometry={rig.geometry}
      material={rig.material}
      onBeforeRender={rig.handleBeforeRender}
      onPointerDown={(event) => {
        rig.detonate({
          x: (event.pointer.x + 1) / 2,
          y: (event.pointer.y + 1) / 2,
        });
        invalidate();
      }}
      raycast={hitEverywhere}
    />
  );
};

import { Color, ShaderMaterial, Vector2, Vector3 } from "three";
import type { IUniform, Texture } from "three";

import { blueNoiseSize } from "@/registry/ivan/lib/blue-noise";
import {
  createImageCoverUniforms,
  fullscreenVertexShader,
  imageCoverChunk,
} from "@/registry/ivan/lib/image-cover";
import type { ImageCoverUniforms } from "@/registry/ivan/lib/image-cover";
import {
  nearestInkChunk,
  orderedChunk,
  orderedDitherIndex,
} from "@/registry/ivan/lib/ordered-print";
import { paletteSize } from "@/registry/ivan/lib/palette";
import {
  bayerChunk,
  hashChunk,
  valueNoiseChunk,
} from "@/registry/ivan/lib/print-noise";
import {
  printSeparation,
  toneChunk,
  toneCurve,
  toneSeparationChunk,
} from "@/registry/ivan/lib/tone-curve";

export const blastPrintDefaults = {
  auraRadius: 1,
  blasts: 0,
  cell: 3,
  dither: "blue-noise",
  ink: "#0B0B0C",
  paper: "#EDECE8",
  paused: false,
  threshold: 0,
} as const;

export interface BlastPrintUniforms extends ImageCoverUniforms {
  uAura: IUniform<Vector2>;
  uAuraRadius: IUniform<number>;
  uAuraStrength: IUniform<number>;
  uBlast: IUniform<Vector2>;
  uBlueNoise: IUniform<Texture | null>;
  uCell: IUniform<number>;
  uColor: IUniform<number>;
  uDither: IUniform<number>;
  uFront: IUniform<number>;
  uInk: IUniform<Color>;
  uNoiseSize: IUniform<number>;
  uPaper: IUniform<Color>;
  uPalette: IUniform<Vector3[]>;
  uReprint: IUniform<number>;
  uRing: IUniform<number>;
  uThreshold: IUniform<number>;
  uTime: IUniform<number>;
}

const glslFloat = (value: number) => value.toFixed(4);

const fragmentShader = `
  uniform vec3 uInk;
  uniform vec3 uPaper;
  uniform float uCell;
  uniform float uThreshold;
  uniform float uTime;
  uniform vec2 uAura;
  uniform float uAuraRadius;
  uniform float uAuraStrength;
  uniform vec2 uBlast;
  uniform float uRing;
  uniform float uFront;
  uniform float uReprint;
  uniform float uColor;

  const float printContrast = ${glslFloat(toneCurve.contrast)};
  const float colorSpread = 0.3;
  const float tileCells = 6.0;

  ${imageCoverChunk}
  ${hashChunk}
  ${valueNoiseChunk}
  ${bayerChunk}
  ${orderedChunk}
  ${toneChunk}
  ${nearestInkChunk(paletteSize)}

  ${toneSeparationChunk("crispTone", printSeparation)}

  void main() {
    if (uHasImage < 0.5) {
      discard;
    }
    vec2 pixel = gl_FragCoord.xy - uOrigin;
    vec2 cell = floor(pixel / uCell);
    vec2 center = (cell + 0.5) * uCell;
    vec2 stage = center / uResolution.y;

    vec2 uv = coverUv(center / uResolution);
    float lod = imageLod(uCell);

    vec3 color = textureLod(uImage, uv, lod).rgb;
    vec3 blurredColor = textureLod(uImage, uv, lod + 2.3).rgb;
    float luma = dot(color, lumaWeights);
    float blurred = dot(blurredColor, lumaWeights);
    float tone = crispTone(curveTone(luma, blurred, printContrast, 1.0));
    vec3 print = curveColor(color, blurredColor, printContrast, 1.0);

    vec2 fromAura = stage - uAura / uResolution.y;
    float above = step(0.0, fromAura.y);
    vec2 shaped = vec2(fromAura.x * 1.2, fromAura.y * mix(1.0, 0.45, above)) / max(uAuraRadius, 0.001);
    float heat = exp(-dot(shaped, shaped) * 1.25) * uAuraStrength;
    float tongue = valueNoise(vec2(cell.x * 0.14, cell.y * 0.032 - uTime * 3.4));
    float flicker = valueNoise(vec2(cell.x * 0.33, cell.y * 0.09 - uTime * 6.5));
    float field = tongue * 0.78 + flicker * 0.22;
    float flame = step(1.0 - heat * 0.95, field) * step(0.001, uAuraStrength);
    float core = step(1.0 - heat * 0.5, field);
    float rim = flame * step(field, 1.0 - heat * 0.95 + 0.04);
    float isNegative = flame * (1.0 - core);
    tone = mix(tone, 1.0 - tone, isNegative);
    print = mix(print, 1.0 - print, isNegative);

    float level = orderedLevel(cell);
    float isInk = max(step(tone - uThreshold - level, -0.0001), rim);

    vec3 printed = mix(uPaper, uInk, isInk);

    float aspect = uResolution.x / uResolution.y;
    float diagonal = length(vec2(aspect, 1.0));
    vec2 blast = uBlast / uResolution.y;
    float blastDistance = length(stage - blast);
    float ragged = (valueNoise(cell * 0.2) - 0.5) * 0.07;
    float swept = step(blastDistance + ragged, uRing);
    vec2 tile = floor(cell / tileCells);
    vec2 tileStage = (tile + 0.5) * tileCells * uCell / uResolution.y;
    float order = clamp(length(tileStage - blast) / diagonal * 0.82 + hash(tile + 17.0) * 0.18, 0.0, 1.0);
    float reprinted = step(order, uReprint) * step(0.001, uReprint);
    vec3 colorPrint = toLinear(nearestInk(print - uThreshold + (level - 0.5) * colorSpread));
    float isColor = swept * reprinted * step(order, uColor) * step(0.001, uColor);
    printed = mix(printed, colorPrint, isColor);

    float frontOffset = (blastDistance + ragged - uRing) / 0.04;
    float front = exp(-frontOffset * frontOffset) * uFront;
    float isFront = step(level, front) * step(0.001, front);
    printed = mix(printed, uPaper, swept * (1.0 - reprinted));
    printed = mix(printed, uInk, isFront);

    gl_FragColor = vec4(printed, 1.0);
    #include <colorspace_fragment>
  }
`;

const createUniforms = (): BlastPrintUniforms => ({
  ...createImageCoverUniforms(),
  uAura: { value: new Vector2(0, 0) },
  uAuraRadius: { value: 0.24 },
  uAuraStrength: { value: 0 },
  uBlast: { value: new Vector2(0, 0) },
  uBlueNoise: { value: null },
  uCell: { value: blastPrintDefaults.cell },
  uColor: { value: 0 },
  uDither: { value: orderedDitherIndex(blastPrintDefaults.dither) },
  uFront: { value: 0 },
  uInk: { value: new Color(blastPrintDefaults.ink) },
  uNoiseSize: { value: blueNoiseSize },
  uPalette: {
    value: Array.from({ length: paletteSize }, () => new Vector3()),
  },
  uPaper: { value: new Color(blastPrintDefaults.paper) },
  uReprint: { value: 1 },
  uRing: { value: 0 },
  uThreshold: { value: blastPrintDefaults.threshold },
  uTime: { value: 0 },
});

export class BlastPrintMaterial extends ShaderMaterial {
  declare uniforms: BlastPrintUniforms;

  constructor() {
    super({
      depthTest: false,
      depthWrite: false,
      fragmentShader,
      toneMapped: false,
      uniforms: createUniforms(),
      vertexShader: fullscreenVertexShader,
    });
  }
}

export const ringLength = 0.3;
export const reprintLength = 0.75;
export const colorHoldLength = 1.1;
export const colorFadeLength = 0.8;
export const blastLength =
  ringLength + reprintLength + colorHoldLength + colorFadeLength;
export const rearmAfter = ringLength + reprintLength;
export const ringReach = 2.2;

export interface BlastFrame {
  ring: number;
  front: number;
  reprint: number;
  color: number;
}

export const idleFrame: BlastFrame = {
  color: 0,
  front: 0,
  reprint: 1,
  ring: 0,
};

const easeOutCubic = (progress: number) => 1 - (1 - progress) ** 3;
const easeOutQuad = (progress: number) => 1 - (1 - progress) ** 2;
const easeInOutCubic = (progress: number) =>
  progress < 0.5 ? 4 * progress ** 3 : 1 - (-2 * progress + 2) ** 3 / 2;

export const blastFrame = (age: number): BlastFrame => {
  if (!(age >= 0) || age >= blastLength) {
    return idleFrame;
  }
  if (age < ringLength) {
    const progress = age / ringLength;
    return {
      color: 0,
      front: (1 - progress) ** 2,
      reprint: 0,
      ring: ringReach * easeOutCubic(progress),
    };
  }
  const reprintAge = age - ringLength;
  const fadeAge = reprintAge - reprintLength - colorHoldLength;
  return {
    color:
      fadeAge <= 0
        ? 1
        : 1 - easeInOutCubic(Math.min(fadeAge / colorFadeLength, 1)),
    front: 0,
    reprint: easeOutQuad(Math.min(reprintAge / reprintLength, 1)),
    ring: ringReach,
  };
};

export type BlastMode = "running" | "still";

export interface StagePoint {
  x: number;
  y: number;
}

export interface Blast {
  time: number;
  firedAt: number;
  origin: StagePoint;
  frame: BlastFrame;
}

export const createBlast = (): Blast => ({
  firedAt: -Infinity,
  frame: idleFrame,
  origin: { x: 0.5, y: 0.5 },
  time: 0,
});

export interface BlastStep {
  step: number;
  mode: BlastMode;
  request: StagePoint | null;
}

export const advanceBlast = (
  blast: Blast,
  { step, mode, request }: BlastStep
) => {
  if (mode === "still") {
    blast.firedAt = -Infinity;
    blast.frame = idleFrame;
    return blast;
  }
  blast.time += step;
  if (request && blast.time - blast.firedAt >= rearmAfter) {
    blast.firedAt = blast.time;
    blast.origin = { x: request.x, y: request.y };
  }
  blast.frame = blastFrame(blast.time - blast.firedAt);
  return blast;
};

"use client";

import { Canvas } from "@react-three/fiber";
import { useRef } from "react";
import type { ComponentProps, ReactNode } from "react";

import { cn } from "@/lib/utils";
import { useInView } from "@/registry/ivan/hooks/use-in-view";
import { usePrefersReducedMotion } from "@/registry/ivan/hooks/use-prefers-reduced-motion";
import { useWebGLSupport } from "@/registry/ivan/hooks/use-webgl-support";

export interface CanvasStageProps {
  ground: string;
  label: string;
  paused: boolean;
  fallback: ReactNode;
  antialias?: boolean;
  camera?: ComponentProps<typeof Canvas>["camera"];
  className?: string;
  children: (isAnimating: boolean) => ReactNode;
}

interface ImageFallbackProps {
  src: string;
  focus: { x: number; y: number };
}

export const ImageFallback = ({ src, focus }: ImageFallbackProps) => (
  <div
    aria-hidden
    className="absolute inset-0 grayscale"
    style={{
      backgroundImage: `url(${JSON.stringify(src)})`,
      backgroundPosition: `${focus.x * 100}% ${focus.y * 100}%`,
      backgroundSize: "cover",
    }}
  />
);

export const CanvasStage = ({
  ground,
  label,
  paused,
  fallback,
  antialias = false,
  camera,
  className,
  children,
}: CanvasStageProps) => {
  const frame = useRef<HTMLElement>(null);
  const hasWebGL = useWebGLSupport();
  const isInView = useInView(frame);
  const prefersReducedMotion = usePrefersReducedMotion();
  const isAnimating = isInView && !prefersReducedMotion && !paused;

  return (
    <figure
      aria-label={label}
      className={cn(
        "relative m-0 aspect-4/3 w-full overflow-hidden",
        className
      )}
      ref={frame}
      style={{ backgroundColor: ground }}
    >
      {hasWebGL ? (
        <Canvas
          aria-hidden
          camera={camera}
          dpr={[1, 1.75]}
          frameloop={isAnimating ? "always" : "demand"}
          gl={{
            alpha: true,
            antialias,
            powerPreference: "high-performance",
          }}
        >
          {children(isAnimating)}
        </Canvas>
      ) : (
        fallback
      )}
    </figure>
  );
};

import { Vector2, Vector4 } from "three";
import type { IUniform, Texture, WebGLRenderer } from "three";

export interface CoverSource {
  texture: Texture;
  width: number;
  height: number;
}

export interface ImageFocus {
  x: number;
  y: number;
}

export const centeredFocus: ImageFocus = { x: 0.5, y: 0.5 };

export const fullscreenVertexShader = `
  void main() {
    gl_Position = vec4(position.xy * 2.0, 0.0, 1.0);
  }
`;

export const imageCoverChunk = `
  uniform vec2 uOrigin;
  uniform vec2 uResolution;
  uniform sampler2D uImage;
  uniform vec2 uImageSize;
  uniform vec2 uFocus;
  uniform float uHasImage;

  const vec3 lumaWeights = vec3(0.2126, 0.7152, 0.0722);

  vec2 imageSpan() {
    float stageAspect = uResolution.x / uResolution.y;
    float imageAspect = uImageSize.x / uImageSize.y;
    return stageAspect > imageAspect
      ? vec2(1.0, imageAspect / stageAspect)
      : vec2(stageAspect / imageAspect, 1.0);
  }

  vec2 coverUv(vec2 stage) {
    vec2 span = imageSpan();
    vec2 start = clamp(uFocus - span * 0.5, vec2(0.0), vec2(1.0) - span);
    return start + stage * span;
  }

  float imageLuma(vec2 uv, float lod) {
    return dot(textureLod(uImage, uv, lod).rgb, lumaWeights);
  }

  float imageLod(float footprint) {
    float texels = footprint * imageSpan().y * uImageSize.y / uResolution.y;
    return log2(max(texels, 1.0));
  }
`;

export interface ImageCoverUniforms {
  [uniform: string]: IUniform;
  uFocus: IUniform<Vector2>;
  uHasImage: IUniform<number>;
  uImage: IUniform<Texture | null>;
  uImageSize: IUniform<Vector2>;
  uOrigin: IUniform<Vector2>;
  uResolution: IUniform<Vector2>;
}

export const createImageCoverUniforms = (): ImageCoverUniforms => ({
  uFocus: { value: new Vector2(0.5, 0.5) },
  uHasImage: { value: 0 },
  uImage: { value: null },
  uImageSize: { value: new Vector2(1, 1) },
  uOrigin: { value: new Vector2(0, 0) },
  uResolution: { value: new Vector2(1, 1) },
});

export const setCoverImage = (
  uniforms: ImageCoverUniforms,
  image: CoverSource | null,
  focus: ImageFocus
) => {
  uniforms.uImage.value = image?.texture ?? null;
  uniforms.uHasImage.value = image ? 1 : 0;
  uniforms.uImageSize.value.set(image?.width ?? 1, image?.height ?? 1);
  uniforms.uFocus.value.set(focus.x, 1 - focus.y);
};

const viewport = new Vector4();

export const readViewport = (
  uniforms: ImageCoverUniforms,
  renderer: WebGLRenderer
) => {
  renderer.getCurrentViewport(viewport);
  uniforms.uOrigin.value.set(viewport.x, viewport.y);
  uniforms.uResolution.value.set(viewport.z, viewport.w);
  return viewport;
};

export const hashChunk = `
  float hash(vec2 point) {
    return fract(sin(dot(point, vec2(127.1, 311.7))) * 43758.5453);
  }
`;

export const valueNoiseChunk = `
  float valueNoise(vec2 point) {
    vec2 whole = floor(point);
    vec2 part = fract(point);
    vec2 blend = part * part * (3.0 - 2.0 * part);
    return mix(
      mix(hash(whole), hash(whole + vec2(1.0, 0.0)), blend.x),
      mix(hash(whole + vec2(0.0, 1.0)), hash(whole + vec2(1.0, 1.0)), blend.x),
      blend.y
    );
  }
`;

export const bayerChunk = `
  float bayer2(vec2 cell) {
    cell = floor(cell);
    return fract(cell.x / 2.0 + cell.y * cell.y * 0.75);
  }

  float bayer4(vec2 cell) {
    return bayer2(0.5 * cell) * 0.25 + bayer2(cell);
  }

  float bayer8(vec2 cell) {
    return bayer4(0.5 * cell) * 0.25 + bayer2(cell) + 0.5 / 64.0;
  }
`;

export const orderedDithers = [
  "bayer-2",
  "bayer-4",
  "bayer-8",
  "blue-noise",
] as const;

export type OrderedDither = (typeof orderedDithers)[number];

export const orderedDitherIndex = (mode: OrderedDither) =>
  orderedDithers.indexOf(mode);

export const orderedChunk = `
  uniform sampler2D uBlueNoise;
  uniform float uNoiseSize;
  uniform float uDither;

  float orderedLevel(vec2 cell) {
    if (uDither < 0.5) {
      return bayer2(cell) + 0.125;
    }
    if (uDither < 1.5) {
      return bayer4(cell) + 0.5 / 16.0;
    }
    if (uDither < 2.5) {
      return bayer8(cell);
    }
    return texture(uBlueNoise, (cell + 0.5) / uNoiseSize).r;
  }

  vec3 toLinear(vec3 color) {
    return mix(
      color / 12.92,
      pow((color + 0.055) / 1.055, vec3(2.4)),
      step(vec3(0.04045), color)
    );
  }
`;

export const nearestInkChunk = (size: number) => `
  uniform vec3 uPalette[${size}];

  vec3 nearestInk(vec3 color) {
    vec3 best = uPalette[0];
    float bestGap = 1e9;
    for (int index = 0; index < ${size}; index++) {
      vec3 difference = (color - uPalette[index]) * vec3(0.9, 1.2, 0.7);
      float gap = dot(difference, difference);
      if (gap < bestGap) {
        bestGap = gap;
        best = uPalette[index];
      }
    }
    return best;
  }
`;

export const toneCurve = {
  black: 0.04,
  contrast: 1.35,
  detail: 1.4,
  gamma: 1,
  white: 0.9,
} as const;

const glslFloat = (value: number) => value.toFixed(4);

export const toneChunk = `
  float curveTone(float luma, float blurred, float contrast, float gamma) {
    float sharpened = luma + (luma - blurred) * ${glslFloat(toneCurve.detail)};
    float level = pow(clamp((sharpened - ${glslFloat(toneCurve.black)}) / ${glslFloat(toneCurve.white - toneCurve.black)}, 0.0, 1.0), gamma);
    return clamp((level - 0.5) * contrast + 0.5, 0.0, 1.0);
  }

  vec3 curveColor(vec3 color, vec3 blurred, float contrast, float gamma) {
    return vec3(
      curveTone(color.r, blurred.r, contrast, gamma),
      curveTone(color.g, blurred.g, contrast, gamma),
      curveTone(color.b, blurred.b, contrast, gamma)
    );
  }
`;

export interface ToneSeparation {
  low: number;
  high: number;
  amount: number;
}

export const printSeparation: ToneSeparation = {
  amount: 0.55,
  high: 0.84,
  low: 0.16,
};

export const toneSeparationChunk = (
  name: string,
  { low, high, amount }: ToneSeparation
) => `
  float ${name}(float tone) {
    return mix(tone, smoothstep(${glslFloat(low)}, ${glslFloat(high)}, tone), ${glslFloat(amount)});
  }
`;

export type Rgb = readonly [number, number, number];

export const paletteSize = 12;

interface Box {
  pixels: Rgb[];
  channel: 0 | 1 | 2;
  range: number;
}

const channels = [0, 1, 2] as const;

const measure = (pixels: Rgb[]): Box => {
  let channel: 0 | 1 | 2 = 0;
  let range = -1;
  for (const index of channels) {
    let low = 255;
    let high = 0;
    for (const pixel of pixels) {
      low = Math.min(low, pixel[index]);
      high = Math.max(high, pixel[index]);
    }
    if (high - low > range) {
      range = high - low;
      channel = index;
    }
  }
  return { channel, pixels, range };
};

const splitPriority = (box: Box) => box.range * Math.sqrt(box.pixels.length);

const average = (pixels: Rgb[]): Rgb => {
  let red = 0;
  let green = 0;
  let blue = 0;
  for (const pixel of pixels) {
    red += pixel[0];
    green += pixel[1];
    blue += pixel[2];
  }
  return [
    Math.round(red / pixels.length),
    Math.round(green / pixels.length),
    Math.round(blue / pixels.length),
  ];
};

const chromaWeight = 6;

const chromaOf = (pixel: Rgb) => Math.max(...pixel) - Math.min(...pixel);

const lumaOf = ([red, green, blue]: Rgb) =>
  0.2126 * red + 0.7152 * green + 0.0722 * blue;

const inkSaturation = 1.55;
const inkContrast = 1.18;

const clampChannel = (value: number) =>
  Math.round(Math.min(Math.max(value, 0), 255));

const printInk = (color: Rgb): Rgb => {
  const luma = lumaOf(color);
  const printed = (luma - 128) * inkContrast + 128;
  return [
    clampChannel(printed + (color[0] - luma) * inkSaturation),
    clampChannel(printed + (color[1] - luma) * inkSaturation),
    clampChannel(printed + (color[2] - luma) * inkSaturation),
  ];
};

export const extractPalette = (rgb: Uint8Array, size = paletteSize) => {
  const pixels: Rgb[] = [];
  for (let offset = 0; offset + 2 < rgb.length; offset += 3) {
    const pixel: Rgb = [
      rgb[offset] ?? 0,
      rgb[offset + 1] ?? 0,
      rgb[offset + 2] ?? 0,
    ];
    const copies = 1 + Math.round((chromaOf(pixel) / 255) * chromaWeight);
    for (let copy = 0; copy < copies; copy += 1) {
      pixels.push(pixel);
    }
  }
  const boxes = [measure(pixels)];
  while (boxes.length < size) {
    let widest = 0;
    for (const [index, box] of boxes.entries()) {
      const current = boxes[widest];
      if (current && splitPriority(box) > splitPriority(current)) {
        widest = index;
      }
    }
    const box = boxes[widest];
    if (!box || box.pixels.length < 2 || box.range === 0) {
      break;
    }
    const sorted = box.pixels.toSorted(
      (first, second) =>
        first[box.channel] - second[box.channel] ||
        lumaOf(first) - lumaOf(second)
    );
    const middle = Math.floor(sorted.length / 2);
    boxes.splice(
      widest,
      1,
      measure(sorted.slice(0, middle)),
      measure(sorted.slice(middle))
    );
  }
  return boxes
    .map((box) => printInk(average(box.pixels)))
    .toSorted((first, second) => lumaOf(first) - lumaOf(second));
};

const sampleColumns = 120;

const greyRamp = Array.from({ length: paletteSize }, (_, step): Rgb => {
  const level = Math.round((step / (paletteSize - 1)) * 255);
  return [level, level, level];
});

const padPalette = (palette: readonly Rgb[]) => {
  const last = palette.at(-1);
  if (!last) {
    return greyRamp;
  }
  return Array.from(
    { length: paletteSize },
    (_, index) => palette[index] ?? last
  );
};

export const samplePalette = (image: HTMLImageElement): readonly Rgb[] => {
  if (image.naturalWidth === 0) {
    return greyRamp;
  }
  const rows = Math.max(
    Math.round((sampleColumns * image.naturalHeight) / image.naturalWidth),
    1
  );
  try {
    const canvas = document.createElement("canvas");
    canvas.width = sampleColumns;
    canvas.height = rows;
    const context = canvas.getContext("2d", { willReadFrequently: true });
    if (!context) {
      return greyRamp;
    }
    context.drawImage(image, 0, 0, sampleColumns, rows);
    const { data } = context.getImageData(0, 0, sampleColumns, rows);
    const rgb = new Uint8Array((data.length / 4) * 3);
    for (let index = 0; index < data.length / 4; index += 1) {
      rgb[index * 3] = data[index * 4] ?? 0;
      rgb[index * 3 + 1] = data[index * 4 + 1] ?? 0;
      rgb[index * 3 + 2] = data[index * 4 + 2] ?? 0;
    }
    return padPalette(extractPalette(rgb));
  } catch {
    return greyRamp;
  }
};

import {
  DataTexture,
  NearestFilter,
  RedFormat,
  RepeatWrapping,
  UnsignedByteType,
} from "three";

export const blueNoiseSize = 64;

const blueNoiseTile =
  "";

export const createBlueNoiseTexture = () => {
  const bytes = Uint8Array.from(
    atob(blueNoiseTile),
    (character) => character.codePointAt(0) ?? 0
  );
  const texture = new DataTexture(
    bytes,
    blueNoiseSize,
    blueNoiseSize,
    RedFormat,
    UnsignedByteType
  );
  texture.generateMipmaps = false;
  texture.magFilter = NearestFilter;
  texture.minFilter = NearestFilter;
  texture.wrapS = RepeatWrapping;
  texture.wrapT = RepeatWrapping;
  texture.needsUpdate = true;
  return texture;
};

export interface Spring {
  value: number;
  velocity: number;
}

export interface SpringConfig {
  stiffness: number;
  damping: number;
}

export const createSpring = (value: number): Spring => ({
  value,
  velocity: 0,
});

export const driveSpring = (
  spring: Spring,
  target: number,
  { stiffness, damping }: SpringConfig,
  step: number,
  isAnimating: boolean
) => {
  if (isAnimating) {
    const acceleration =
      stiffness * (target - spring.value) - damping * spring.velocity;
    spring.velocity += acceleration * step;
    spring.value += spring.velocity * step;
  } else {
    spring.value = target;
    spring.velocity = 0;
  }
};

export const frameStep = (delta: number) => Math.min(delta, 1 / 30);

export interface PointerSample {
  x: number;
  y: number;
}

const holdAfterMove = 2.5;
const movedBy = 0.0001;

export class PointerTrace {
  x = 0.5;
  y = 0.5;
  isActive = false;
  private hasMoved = false;
  private idle = 0;

  update({ x, y }: PointerSample, step: number, isAnimating: boolean) {
    const nextX = (x + 1) / 2;
    const nextY = (y + 1) / 2;
    if (Math.abs(nextX - this.x) + Math.abs(nextY - this.y) > movedBy) {
      this.hasMoved = true;
      this.idle = 0;
    } else {
      this.idle += step;
    }
    this.x = nextX;
    this.y = nextY;
    this.isActive =
      this.hasMoved && (!isAnimating || this.idle < holdAfterMove);
  }
}

